Task ID: nrf_l1_udp_reflector
Category: network_routing_forwarding
Difficulty: level_1

Original Instruction:
Write a complete XDP/eBPF program that reflects valid IPv4 UDP packets at Layer 2 by swapping the Ethernet source and destination MAC addresses and returning XDP_TX. Pass every other packet (TCP, ICMP, non-IPv4, and malformed frames) unchanged with XDP_PASS.

Technical Requirements:
- Check Ethernet and IPv4 bounds
- Verify eth->h_proto == bpf_htons(ETH_P_IP)
- Verify ip->protocol == IPPROTO_UDP
- Check UDP header bounds
- Swap eth->h_source and eth->h_dest (using a 6-byte temporary buffer or __u16/__u32 swaps)
- Return XDP_TX for valid IPv4 UDP packets
- Return XDP_PASS for all other packets
- GPL license and SEC("xdp") entry point

Previous Implementation:
```c
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/ipv6.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <linux/icmp.h>
#include <linux/in.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>


SEC("xdp")
int xdp_reflect_nrf_l1_udp(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;

    if (ip->protocol != IPPROTO_UDP)
        return XDP_PASS;

    unsigned int ip_hdr_len = ip->ihl * 4;
    if (ip_hdr_len < sizeof(struct iphdr) || (void *)ip + ip_hdr_len > data_end)
        return XDP_PASS;

    struct udphdr *udp = (void *)ip + ip_hdr_len;
    if ((void *)(udp + 1) > data_end)
        return XDP_PASS;

    __u8 *tmp = eth->h_source;
    eth->h_source = eth->h_dest;
    eth->h_dest = tmp;

    return XDP_TX;
}

char _license[] SEC("license") = "GPL";
```

