Task ID: nrf_l3_flow_load_balancer
Category: network_routing_forwarding
Difficulty: level_3

Original Instruction:
Write an XDP/eBPF 5-tuple flow load balancer. Define: (1) 'backend_macs' array map (type BPF_MAP_TYPE_ARRAY, key __u32 [0 or 1], val unsigned char[6], max_entries 2), (2) 'backend_devmap' (type BPF_MAP_TYPE_DEVMAP, key __u32, val __u32, max_entries 2). For each IPv4 TCP/UDP packet, compute flow hash = (saddr ^ daddr ^ (sport << 16 | dport) ^ proto) % 2. Lookup backend MAC at key 'hash' in 'backend_macs' and copy into eth->h_dest. Then redirect packet via bpf_redirect_map(&backend_devmap, hash, 0). If devmap lookup fails or for non-TCP/UDP / non-IPv4 traffic, return XDP_PASS.

Technical Requirements:
- Define 'backend_macs' array map (key __u32, val unsigned char[6], max_entries 2)
- Define 'backend_devmap' DEVMAP (max_entries 2)
- Check Ethernet and IPv4 bounds
- Verify ip->protocol is IPPROTO_TCP or IPPROTO_UDP and parse L4 ports safely
- Compute backend_idx = (ip->saddr ^ ip->daddr ^ (sport << 16 | dport) ^ ip->protocol) & 1
- Lookup backend MAC: if present, copy to eth->h_dest
- Redirect via bpf_redirect_map(&backend_devmap, backend_idx, 0)
- Return XDP_PASS for non-TCP/UDP and non-IPv4
- GPL license and SEC("xdp") entry point

Previous Implementation:
```c
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/ipv6.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <linux/icmp.h>
#include <linux/in.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>


struct {
    __uint(type, BPF_MAP_TYPE_ARRAY);
    __uint(max_entries, 2);
    __type(key, __u32);
    __type(value, unsigned char[ETH_ALEN]);
} backend_macs_1 SEC(".maps");

struct {
    __uint(type, BPF_MAP_TYPE_DEVMAP);
    __uint(max_entries, 2);
    __type(key, __u32);
    __type(value, __u32);
} backend_devmap_1 SEC(".maps");

SEC("xdp")
int xdp_flow_load_balancer_nrf_l3(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;

    if (ip->protocol != IPPROTO_TCP && ip->protocol != IPPROTO_UDP)
        return XDP_PASS;

    unsigned int ip_hdr_len = ip->ihl * 4;
    if (ip_hdr_len < sizeof(struct iphdr) || (void *)ip + ip_hdr_len > data_end)
        return XDP_PASS;

    if (ip->protocol == IPPROTO_TCP) {
        unsigned int tcp_hdr_len = ip->protocol == IPPROTO_TCP ? ip->tlc : 0;
        if (tcp_hdr_len < sizeof(struct tcphdr) || (void *)ip + ip_hdr_len + tcp_hdr_len > data_end)
            return XDP_PASS;
        struct tcphdr *tcp = (void *)ip + ip_hdr_len;
        __u16 sport = tcp->source;
        __u16 dport = tcp->dest;
        if ((void *)(tcp + 1) > data_end)
            return XDP_PASS;
        __u32 saddr = ip->saddr;
        __u32 daddr = ip->daddr;
        __u8  proto = ip->protocol;
        __u32 hash = (saddr ^ daddr ^ (sport << 16 | dport) ^ proto) & 1;
        unsigned char *mac = bpf_map_lookup_elem(&backend_macs_1, &hash);
        if (mac) {
            __builtin_memcpy(eth->h_dest, mac, ETH_ALEN);
        }
        __u32 dev_idx = hash;
        __u32 *dev = bpf_map_lookup_elem(&backend_devmap_1, &dev_idx);
        if (dev) {
            return bpf_redirect_map(&backend_devmap_1, dev_idx, 0);
        }
        return XDP_PASS;
    } else { // UDP
        __u32 saddr = ip->saddr;
        __u32 daddr = ip->daddr;
        __u8  proto = ip->protocol;
        __u16 sport = ip->check;
        __u16 dport = ip->ttl;
        __u32 hash = (saddr ^ daddr ^ (sport << 16 | dport) ^ proto) & 1;
        unsigned char *mac = bpf_map_lookup_elem(&backend_macs_1, &hash);
        if (mac) {
            __builtin_memcpy(eth->h_dest, mac, ETH_ALEN);
        }
        __u32 dev_idx = hash;
        __u32 *dev = bpf_map_lookup_elem(&backend_devmap_1, &dev_idx);
        if (dev) {
            return bpf_redirect_map(&backend_devmap_1, dev_idx, 0);
        }
        return XDP_PASS;
    }
}

char _license[] SEC("license") = "GPL";
```

