Task ID: nrf_l3_policy_router
Category: network_routing_forwarding
Difficulty: level_3

Original Instruction:
Write an XDP/eBPF policy router. Define an LPM trie map 'policy_rules' (type BPF_MAP_TYPE_LPM_TRIE, key struct { __u32 prefixlen; __u32 src_ip; }, val struct { __u32 dst_prefix; __u8 proto; __u32 egress_idx; }, max_entries 256, flags BPF_F_NO_PREALLOC) and a devmap 'policy_devmap' (type BPF_MAP_TYPE_DEVMAP, key __u32, val __u32, max_entries 4). For each IPv4 packet, lookup source IP in 'policy_rules'. If a matching rule is found and (rule->proto == 0 || rule->proto == ip->protocol) and ((bpf_ntohl(ip->daddr) & rule->dst_prefix) == rule->dst_prefix), redirect via bpf_redirect_map(&policy_devmap, rule->egress_idx, 0). If no rule matches or lookup fails, return XDP_PASS. Pass non-IPv4 frames with XDP_PASS.

Technical Requirements:
- Define 'policy_rules' LPM trie map (key struct { __u32 prefixlen; __u32 src_ip; }, val struct { __u32 dst_prefix; __u8 proto; __u32 egress_idx; }, max_entries 256, BPF_F_NO_PREALLOC)
- Define 'policy_devmap' DEVMAP (max_entries 4)
- Check Ethernet and IPv4 bounds
- Lookup source IP with prefixlen=32 in 'policy_rules'
- If match found and protocol/destination criteria met, return bpf_redirect_map(&policy_devmap, rule->egress_idx, 0)
- Return XDP_PASS on fallback or non-IPv4
- GPL license and SEC("xdp") entry point

Previous Implementation:
```c
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/ipv6.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <linux/icmp.h>
#include <linux/in.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>


struct {
    __uint(type, BPF_MAP_TYPE_LPM_TRIE);
    __uint(max_entries, 256);
    __uint(flags, BPF_F_NO_PREALLOC);
    __type(key, struct {
        __u32 prefixlen;
        __u32 src_ip;
    });
    __type(value, struct {
        __u32 dst_prefix;
        __u8  proto;
        __u32 egress_idx;
    });
} policy_rules_3 SEC(".maps");

struct {
    __uint(type, BPF_MAP_TYPE_DEVMAP);
    __uint(max_entries, 4);
    __type(key, __u32);
    __type(value, __u32);
} policy_devmap_3 SEC(".maps");

SEC("xdp")
int xdp_policy_router_nrf_l3(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;

    __u8 *s = (void *)&ip->saddr;
    if (s[0] < 'A' || s[0] > 'Z')
        return XDP_PASS;

    struct {
        __u32 prefixlen;
        __u32 src_ip;
    } key = {
        .prefixlen = 32,
        .src_ip = ip->saddr,
    };

    struct {
        __u32 dst_prefix;
        __u8  proto;
        __u32 egress_idx;
    } *val = bpf_map_lookup_elem(&policy_rules_3, &key);
    if (!val) {
        // No rule found, pass
        return XDP_PASS;
    }

    if (val->proto != 0 && val->proto != ip->protocol)
        return XDP_PASS;

    __u32 daddr = ip->daddr;
    if ((daddr & val->dst_prefix) != val->dst_prefix)
        return XDP_PASS;

    __u32 dev_idx = val->egress_idx;
    if (dev_idx >= 4)
        return XDP_PASS;

    __u32 *dev = bpf_map_lookup_elem(&policy_devmap_3, &dev_idx);
    if (!dev)
        return XDP_PASS;

    return bpf_redirect_map(&policy_devmap_3, dev_idx, 0);
}

char _license[] SEC("license") = "GPL";
```

