    csum += (__u32)d[1] - (__u32)0xA8;
    csum += (__u32)d[2] - (__u32)0x64;
    csum += (__u32)d[3] - (__u32)0x32;
    while (csum >> 16)
        csum = (csum & 0xFFFF) + (csum >> 16);
    ip->check = (__u16)csum;

    // Incremental checksum adjustment for port change
    __u16 *p = (__u16 *)tcp + 2;
    __u32 csum = (__u32)*p + (__u32)8080 - (__u32)tcp->dest;
    while (csum >> 16)
        csum = (csum & 0xFFFF) + (csum >> 16);
    *p = (__u16)csum;

    return XDP_PASS;
}

